from scipy.optimize import least_squares
t=np.asarray(df['t']);A=np.asarray(df['A']);y=np.asarray(df['dA_dt'])
def nm(p): return np.sum(p**2)/np.sum((y-y.mean())**2)
def model(p):
    return p[0]*np.log(1+p[1]*t)*A**2 + p[2]*t**p[3]*A**p[4] + p[5]*t**p[6]*A**p[7]+p[8]*A**p[9]
best=None
rng=np.random.default_rng(0)
for trial in range(60):
    p0=np.r_[rng.normal(0,3),rng.uniform(0.05,3),rng.normal(0,3),rng.uniform(-2,2),rng.uniform(-2,2),rng.normal(0,3),rng.uniform(-2,2),rng.uniform(-2,2),rng.normal(0,3),rng.uniform(-2,2)]
    try:
        r=least_squares(lambda p: model(p)-y,p0,max_nfev=3000)
        v=nm(r.fun)
        if best is None or v<best[0]: best=(v,np.round(r.x,4))
    except Exception as e: pass
